package dev.langchain4j.opentelemetry;

import dev.langchain4j.observability.api.listener.*;
import dev.langchain4j.observability.api.event.*;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.context.Context;
import io.opentelemetry.api.trace.StatusCode;

public class OpenTelemetryAiServiceListener implements 
        AiServiceStartedListener,
        AiServiceResponseReceivedListener,
        AiServiceCompletedListener,
        AiServiceErrorListener {

    private final Tracer tracer;
    private static final String SPAN_KEY = "otel.span";

    public OpenTelemetryAiServiceListener(Tracer tracer) {
        this.tracer = tracer;
    }

    @Override
    public void onEvent(AiServiceStartedEvent event) {
        String spanName = String.format("AiService.%s.%s",
            event.invocationContext().interfaceName(),
            event.invocationContext().methodName());

        Span span = tracer.spanBuilder(spanName)
            .setSpanKind(SpanKind.INTERNAL)
            .startSpan();

        span.setAttribute("invocation.id", event.invocationContext().invocationId().toString());
        span.setAttribute("ai_service.interface", event.invocationContext().interfaceName());
        span.setAttribute("ai_service.method", event.invocationContext().methodName());

        if (event.invocationContext().chatMemoryId() != null) {
            span.setAttribute("chat_memory_id", event.invocationContext().chatMemoryId().toString());
        }

        // Store span in attributes for child operations
        event.invocationContext().attributes().put(SPAN_KEY, span);
    }

    @Override
    public void onEvent(AiServiceCompletedEvent event) {
        Span span = (Span) event.invocationContext().attributes().get(SPAN_KEY);
        if (span != null) {
            span.setStatus(StatusCode.OK);
            span.end();
        }
    }

    @Override
    public void onEvent(AiServiceErrorEvent event) {
        Span span = (Span) event.invocationContext().attributes().get(SPAN_KEY);
        if (span != null) {
            span.setStatus(StatusCode.ERROR, event.error().getMessage());
            span.recordException(event.error());
            span.end();
        }
    }
}

package dev.langchain4j.opentelemetry;

import dev.langchain4j.model.chat.listener.*;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanKind;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.api.trace.StatusCode;

public class OpenTelemetryChatModelListener implements ChatModelListener {

    private final Tracer tracer;
    private final boolean captureContent;
    private final int contentTruncationLength;
    private static final String SPAN_KEY = "otel.chat.span";

    public OpenTelemetryChatModelListener(Tracer tracer) {
        this(tracer, false, 1000);
    }

    public OpenTelemetryChatModelListener(Tracer tracer, boolean captureContent, int truncationLength) {
        this.tracer = tracer;
        this.captureContent = captureContent;
        this.contentTruncationLength = truncationLength;
    }

    @Override
    public void onRequest(ChatModelRequestContext ctx) {
        Span span = tracer.spanBuilder("chat " + ctx.chatRequest().parameters().modelName())
            .setSpanKind(SpanKind.CLIENT)
            .startSpan();

        // GenAI semantic conventions
        span.setAttribute("gen_ai.system", inferSystem(ctx.modelProvider()));
        span.setAttribute("gen_ai.request.model", ctx.chatRequest().parameters().modelName());
        span.setAttribute("gen_ai.operation.name", "chat");

        // Request parameters
        if (ctx.chatRequest().parameters().temperature() != null) {
            span.setAttribute("gen_ai.request.temperature", ctx.chatRequest().parameters().temperature());
        }
        if (ctx.chatRequest().parameters().topP() != null) {
            span.setAttribute("gen_ai.request.top_p", ctx.chatRequest().parameters().topP());
        }
        if (ctx.chatRequest().parameters().maxOutputTokens() != null) {
            span.setAttribute("gen_ai.request.max_tokens", ctx.chatRequest().parameters().maxOutputTokens());
        }

        // Tool count if tools present
        if (ctx.chatRequest().parameters().toolSpecifications() != null) {
            span.setAttribute("gen_ai.request.tool_count", 
                ctx.chatRequest().parameters().toolSpecifications().size());
        }

        // Optional content capture (redacted by default)
        if (captureContent) {
            String content = extractAndTruncateContent(ctx.chatRequest().messages());
            span.setAttribute("gen_ai.request.content", content);
        }

        ctx.attributes().put(SPAN_KEY, span);
    }

    @Override
    public void onResponse(ChatModelResponseContext ctx) {
        Span span = (Span) ctx.attributes().get(SPAN_KEY);
        if (span != null) {
            // Token usage
            if (ctx.chatResponse().metadata().tokenUsage() != null) {
                span.setAttribute("gen_ai.usage.input_tokens", 
                    ctx.chatResponse().metadata().tokenUsage().inputTokenCount());
                span.setAttribute("gen_ai.usage.output_tokens", 
                    ctx.chatResponse().metadata().tokenUsage().outputTokenCount());
            }

            // Response metadata
            if (ctx.chatResponse().metadata().id() != null) {
                span.setAttribute("gen_ai.response.id", ctx.chatResponse().metadata().id());
            }
            if (ctx.chatResponse().metadata().modelName() != null) {
                span.setAttribute("gen_ai.response.model", ctx.chatResponse().metadata().modelName());
            }
            if (ctx.chatResponse().metadata().finishReason() != null) {
                span.setAttribute("gen_ai.response.finish_reasons", 
                    ctx.chatResponse().metadata().finishReason().toString());
            }

            // Optional content capture
            if (captureContent && ctx.chatResponse().aiMessage() != null) {
                String content = truncate(ctx.chatResponse().aiMessage().text(), contentTruncationLength);
                span.setAttribute("gen_ai.response.content", content);
            }

            span.setStatus(StatusCode.OK);
            span.end();
        }
    }

    @Override
    public void onError(ChatModelErrorContext ctx) {
        Span span = (Span) ctx.attributes().get(SPAN_KEY);
        if (span != null) {
            span.setStatus(StatusCode.ERROR, ctx.error().getMessage());
            span.recordException(ctx.error());
            span.setAttribute("error.type", ctx.error().getClass().getName());
            span.end();
        }
    }

    private String inferSystem(String modelProvider) {
        // Map provider to GenAI system name
        if (modelProvider.contains("openai")) return "openai";
        if (modelProvider.contains("anthropic")) return "anthropic";
        return modelProvider;
    }

    private String truncate(String content, int maxLength) {
        if (content == null || content.length() <= maxLength) return content;
        return content.substring(0, maxLength) + "...";
    }

    private String extractAndTruncateContent(List<ChatMessage> messages) {
        // Extract and truncate message content
        return "...";
    }
}

package dev.langchain4j.opentelemetry;

import dev.langchain4j.observability.api.listener.ToolExecutedListener;
import dev.langchain4j.observability.api.event.ToolExecutedEvent;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanKind;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.api.trace.StatusCode;
import io.opentelemetry.context.Context;

public class OpenTelemetryToolExecutionListener implements ToolExecutedListener {

    private final Tracer tracer;
    private final boolean captureParameters;

    public OpenTelemetryToolExecutionListener(Tracer tracer) {
        this(tracer, false);
    }

    public OpenTelemetryToolExecutionListener(Tracer tracer, boolean captureParameters) {
        this.tracer = tracer;
        this.captureParameters = captureParameters;
    }

    @Override
    public void onEvent(ToolExecutedEvent event) {
        // Get parent span from context
        Span parentSpan = (Span) event.invocationContext().attributes().get("otel.span");
        Context parentContext = parentSpan != null ? Context.current().with(parentSpan) : Context.current();

        String spanName = "tool." + event.toolSpecification().name();

        Span span = tracer.spanBuilder(spanName)
            .setParent(parentContext)
            .setSpanKind(SpanKind.INTERNAL)
            .startSpan();

        span.setAttribute("tool.name", event.toolSpecification().name());

        // Optional parameter capture (redacted by default)
        if (captureParameters && event.toolExecutionRequest() != null) {
            span.setAttribute("tool.arguments", event.toolExecutionRequest().arguments());
        }

        // Record result or error
        if (event.result() != null) {
            if (captureParameters) {
                span.setAttribute("tool.result", String.valueOf(event.result()));
            }
            span.setStatus(StatusCode.OK);
        } else if (event.error() != null) {
            span.setStatus(StatusCode.ERROR, event.error().getMessage());
            span.recordException(event.error());
            span.setAttribute("error.type", event.error().getClass().getName());
        }

        span.end();
    }
}

package dev.langchain4j.opentelemetry;

import dev.langchain4j.observability.api.listener.*;
import dev.langchain4j.observability.api.event.*;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanKind;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.api.trace.StatusCode;
import io.opentelemetry.context.Context;

public class OpenTelemetryGuardrailListener implements 
        InputGuardrailExecutedListener,
        OutputGuardrailExecutedListener {

    private final Tracer tracer;

    public OpenTelemetryGuardrailListener(Tracer tracer) {
        this.tracer = tracer;
    }

    @Override
    public void onEvent(InputGuardrailExecutedEvent event) {
        Span parentSpan = (Span) event.invocationContext().attributes().get("otel.span");
        Context parentContext = parentSpan != null ? Context.current().with(parentSpan) : Context.current();

        String spanName = "guardrail.input." + event.guardrailName();

        Span span = tracer.spanBuilder(spanName)
            .setParent(parentContext)
            .setSpanKind(SpanKind.INTERNAL)
            .startSpan();

        span.setAttribute("guardrail.name", event.guardrailName());
        span.setAttribute("guardrail.type", "input");

        if (event.result().isSuccess()) {
            span.setAttribute("guardrail.result", "success");
            span.setStatus(StatusCode.OK);
        } else {
            span.setAttribute("guardrail.result", "blocked");
            if (event.result().reason() != null) {
                span.setAttribute("guardrail.reason", event.result().reason());
            }
            span.setStatus(StatusCode.ERROR, "Input blocked by guardrail");
        }

        span.end();
    }

    @Override
    public void onEvent(OutputGuardrailExecutedEvent event) {
        Span parentSpan = (Span) event.invocationContext().attributes().get("otel.span");
        Context parentContext = parentSpan != null ? Context.current().with(parentSpan) : Context.current();

        String spanName = "guardrail.output." + event.guardrailName();

        Span span = tracer.spanBuilder(spanName)
            .setParent(parentContext)
            .setSpanKind(SpanKind.INTERNAL)
            .startSpan();

        span.setAttribute("guardrail.name", event.guardrailName());
        span.setAttribute("guardrail.type", "output");

        if (event.result().isSuccess()) {
            span.setAttribute("guardrail.result", "success");
            span.setStatus(StatusCode.OK);
        } else if (event.result().isReprompt()) {
            span.setAttribute("guardrail.result", "reprompt");
            span.setAttribute("guardrail.reprompt_count", event.result().repromptAttempt());
            span.setStatus(StatusCode.OK);
        } else {
            span.setAttribute("guardrail.result", "failed");
            if (event.result().reason() != null) {
                span.setAttribute("guardrail.reason", event.result().reason());
            }
            span.setStatus(StatusCode.ERROR, "Output validation failed");
        }

        span.end();
    }
}

package dev.langchain4j.opentelemetry;

import io.opentelemetry.api.metrics.Meter;
import io.opentelemetry.api.metrics.LongCounter;
import io.opentelemetry.api.metrics.DoubleHistogram;
import io.opentelemetry.api.common.Attributes;
import io.opentelemetry.api.common.AttributeKey;

public class OpenTelemetryMetricsRecorder {

    private final LongCounter requestCounter;
    private final DoubleHistogram durationHistogram;
    private final LongCounter llmRequestCounter;
    private final DoubleHistogram llmDurationHistogram;

    private static final AttributeKey<String> INTERFACE_KEY = AttributeKey.stringKey("ai_service.interface");
    private static final AttributeKey<String> METHOD_KEY = AttributeKey.stringKey("ai_service.method");
    private static final AttributeKey<String> STATUS_KEY = AttributeKey.stringKey("status");
    private static final AttributeKey<String> MODEL_KEY = AttributeKey.stringKey("gen_ai.request.model");

    public OpenTelemetryMetricsRecorder(Meter meter) {
        this.requestCounter = meter.counterBuilder("langchain4j.aiservice.requests")
            .setDescription("Number of AI service invocations")
            .setUnit("1")
            .build();

        this.durationHistogram = meter.histogramBuilder("langchain4j.aiservice.duration")
            .setDescription("Duration of AI service invocations")
            .setUnit("ms")
            .build();

        this.llmRequestCounter = meter.counterBuilder("langchain4j.llm.requests")
            .setDescription("Number of LLM requests")
            .setUnit("1")
            .build();

        this.llmDurationHistogram = meter.histogramBuilder("langchain4j.llm.duration")
            .setDescription("Duration of LLM requests")
            .setUnit("ms")
            .build();
    }

    public void recordAiServiceRequest(String interfaceName, String methodName, String status, long durationMs) {
        Attributes attributes = Attributes.builder()
            .put(INTERFACE_KEY, interfaceName)
            .put(METHOD_KEY, methodName)
            .put(STATUS_KEY, status)
            .build();

        requestCounter.add(1, attributes);
        durationHistogram.record(durationMs, attributes);
    }

    public void recordLlmRequest(String model, String status, long durationMs) {
        Attributes attributes = Attributes.builder()
            .put(MODEL_KEY, model)
            .put(STATUS_KEY, status)
            .build();

        llmRequestCounter.add(1, attributes);
        llmDurationHistogram.record(durationMs, attributes);
    }
}

private final LongCounter tokenCounter;
private final LongCounter retryCounter;

private static final AttributeKey<String> TOKEN_TYPE_KEY = AttributeKey.stringKey("token_type");
private static final AttributeKey<String> ERROR_TYPE_KEY = AttributeKey.stringKey("error.type");

// In constructor:
this.tokenCounter = meter.counterBuilder("langchain4j.llm.tokens")
    .setDescription("Number of tokens consumed by LLM requests")
    .setUnit("1")
    .build();

this.retryCounter = meter.counterBuilder("langchain4j.llm.retries")
    .setDescription("Number of LLM request retries")
    .setUnit("1")
    .build();

public void recordTokenUsage(String model, int inputTokens, int outputTokens) {
    if (inputTokens > 0) {
        Attributes inputAttrs = Attributes.builder()
            .put(MODEL_KEY, model)
            .put(TOKEN_TYPE_KEY, "input")
            .build();
        tokenCounter.add(inputTokens, inputAttrs);
    }

    if (outputTokens > 0) {
        Attributes outputAttrs = Attributes.builder()
            .put(MODEL_KEY, model)
            .put(TOKEN_TYPE_KEY, "output")
            .build();
        tokenCounter.add(outputTokens, outputAttrs);
    }
}

public void recordRetry(String model, String errorType) {
    Attributes attributes = Attributes.builder()
        .put(MODEL_KEY, model)
        .put(ERROR_TYPE_KEY, errorType)
        .build();

    retryCounter.add(1, attributes);
}

