import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;

@AutoConfiguration
@ConditionalOnClass(OpenTelemetry.class)
@ConditionalOnProperty(prefix = "langchain4j.opentelemetry", name = "enabled", havingValue = "true", matchIfMissing = true)
@EnableConfigurationProperties(OpenTelemetryProperties.class)
public class OpenTelemetryAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean
    public OpenTelemetry openTelemetry() {
        return OpenTelemetryConfigurer.configureOpenTelemetry();
    }

    @Bean
    @ConditionalOnMissingBean
    public Tracer tracer(OpenTelemetry openTelemetry) {
        return openTelemetry.getTracer("langchain4j");
    }

    @Bean
    @ConditionalOnMissingBean
    public Meter meter(OpenTelemetry openTelemetry) {
        return openTelemetry.getMeter("langchain4j");
    }

    @Bean
    public OpenTelemetryAiServiceListener aiServiceListener(Tracer tracer) {
        return new OpenTelemetryAiServiceListener(tracer);
    }

    @Bean
    public OpenTelemetryChatModelListener chatModelListener(
            Tracer tracer, 
            OpenTelemetryProperties properties) {
        return new OpenTelemetryChatModelListener(
            tracer,
            properties.isCaptureContent(),
            properties.getContentTruncationLength()
        );
    }

    @Bean
    public OpenTelemetryToolExecutionListener toolListener(
            Tracer tracer,
            OpenTelemetryProperties properties) {
        return new OpenTelemetryToolExecutionListener(
            tracer,
            properties.isCaptureParameters()
        );
    }

    @Bean
    public OpenTelemetryGuardrailListener guardrailListener(Tracer tracer) {
        return new OpenTelemetryGuardrailListener(tracer);
    }

    @Bean
    public OpenTelemetryMetricsRecorder metricsRecorder(Meter meter) {
        return new OpenTelemetryMetricsRecorder(meter);
    }
}

