package dev.langchain4j.opentelemetry;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;
import io.opentelemetry.sdk.trace.data.SpanData;
import io.opentelemetry.sdk.testing.exporter.InMemorySpanExporter;

public class PrivacyAndPerformanceTest {

    @Test
    void testDefaultRedaction() {
        // Setup in-memory exporter
        InMemorySpanExporter exporter = InMemorySpanExporter.create();

        // Create listener with default config (redaction ON)
        OpenTelemetryChatModelListener listener = new OpenTelemetryChatModelListener(tracer);

        // Send chat message
        String sensitiveContent = "My SSN is 123-45-6789";
        // ... send message ...

        // Assert content NOT in span attributes
        List<SpanData> spans = exporter.getFinishedSpanItems();
        assertThat(spans).hasSize(1);
        SpanData span = spans.get(0);
        assertThat(span.getAttributes().asMap()).doesNotContainKey("gen_ai.request.content");
        assertThat(span.getAttributes().asMap().values())
            .noneMatch(v -> v.toString().contains("123-45-6789"));
    }

    @Test
    void testOptInContentCaptureWithTruncation() {
        // Setup with content capture enabled
        OpenTelemetryChatModelListener listener = 
            new OpenTelemetryChatModelListener(tracer, true, 1000);

        // Send 5000 character message
        String longMessage = "a".repeat(5000);
        // ... send message ...

        // Assert content truncated to 1000 chars
        SpanData span = exporter.getFinishedSpanItems().get(0);
        String capturedContent = (String) span.getAttributes().get("gen_ai.request.content");
        assertThat(capturedContent).hasSize(1003); // 1000 + "..."
    }

    @Test
    void testAsyncExport() throws InterruptedException {
        // Record thread during span creation
        String creationThread = Thread.currentThread().getName();

        // Create and end span
        // ...

        // Wait briefly for export
        Thread.sleep(100);

        // Verify export happened on different thread
        // (This is handled by OpenTelemetry SDK's BatchSpanProcessor)
        assertThat(creationThread).doesNotContain("BatchSpanProcessor");
    }

    @Test
    void testPerformanceOverhead() {
        // Baseline: 1000 invocations without OpenTelemetry
        long baselineP95 = measureP95Latency(1000, false);

        // With OpenTelemetry: 1000 invocations
        long instrumentedP95 = measureP95Latency(1000, true);

        // Calculate overhead
        double overheadPercent = ((double)(instrumentedP95 - baselineP95) / baselineP95) * 100;

        assertThat(overheadPercent).isLessThan(5.0);
    }

    private long measureP95Latency(int iterations, boolean withOtel) {
        List<Long> latencies = new ArrayList<>();
        for (int i = 0; i < iterations; i++) {
            long start = System.nanoTime();
            // Execute AiService invocation
            long end = System.nanoTime();
            latencies.add(end - start);
        }
        Collections.sort(latencies);
        return latencies.get((int)(iterations * 0.95));
    }
}

// Streaming support extensions
private final boolean emitStreamingEvents;

// Handles streaming responses
@Override
public void onResponse(ChatModelResponseContext ctx) {
    Span span = (Span) ctx.attributes().get(SPAN_KEY);
    if (span == null) return;

    // Check if this is streaming or regular response
    boolean isStreaming = ctx.attributes().containsKey("streaming");

    if (isStreaming) {
        // For streaming, this is called after all chunks received
        // Token usage is in the final aggregated response
        if (ctx.chatResponse().metadata().tokenUsage() != null) {
            span.setAttribute("gen_ai.usage.input_tokens", 
                ctx.chatResponse().metadata().tokenUsage().inputTokenCount());
            span.setAttribute("gen_ai.usage.output_tokens", 
                ctx.chatResponse().metadata().tokenUsage().outputTokenCount());
        }

        // Optional: emit event for streaming completion
        if (emitStreamingEvents) {
            span.addEvent("streaming.completed");
        }
    }

    // Common response handling
    if (ctx.chatResponse().metadata().id() != null) {
        span.setAttribute("gen_ai.response.id", ctx.chatResponse().metadata().id());
    }

    span.setStatus(StatusCode.OK);
    span.end();
}

// Called for each streaming chunk (if implemented)
public void onChunk(String chunk, Context context) {
    if (emitStreamingEvents) {
        Span span = Span.fromContext(context);
        span.addEvent("chunk.received", 
            Attributes.of(AttributeKey.longKey("chunk.length"), (long)chunk.length()));
    }
}

package dev.langchain4j.opentelemetry;

import dev.langchain4j.service.AiServices;
import io.opentelemetry.sdk.testing.exporter.InMemorySpanExporter;
import io.opentelemetry.sdk.testing.exporter.InMemoryMetricExporter;
import io.opentelemetry.sdk.trace.data.SpanData;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

public class OpenTelemetryIntegrationTest {

    @Test
    void testCompleteAiServiceFlowWithOpenTelemetry() {
        // Setup in-memory exporters for testing
        InMemorySpanExporter spanExporter = InMemorySpanExporter.create();
        InMemoryMetricExporter metricExporter = InMemoryMetricExporter.create();

        // Configure OpenTelemetry with test exporters
        OpenTelemetry otel = setupTestOpenTelemetry(spanExporter, metricExporter);
        Tracer tracer = otel.getTracer("test");
        Meter meter = otel.getMeter("test");

        // Create listeners
        OpenTelemetryAiServiceListener aiServiceListener = new OpenTelemetryAiServiceListener(tracer);
        OpenTelemetryChatModelListener chatModelListener = new OpenTelemetryChatModelListener(tracer);
        OpenTelemetryToolExecutionListener toolListener = new OpenTelemetryToolExecutionListener(tracer);
        OpenTelemetryGuardrailListener guardrailListener = new OpenTelemetryGuardrailListener(tracer);
        OpenTelemetryMetricsRecorder metricsRecorder = new OpenTelemetryMetricsRecorder(meter);

        // Create mock ChatModel with listener
        ChatModel mockModel = createMockChatModel(chatModelListener);

        // Define AiService with tool and guardrail
        interface Assistant {
            @UserMessage("Calculate {{input}}")
            String calculate(String input);
        }

        // Build AiService with all listeners
        Assistant assistant = AiServices.builder(Assistant.class)
            .chatModel(mockModel)
            .tools(new CalculatorTool())
            .registerListener(aiServiceListener)
            .registerListener(toolListener)
            .registerListener(guardrailListener)
            .build();

        // Execute
        String result = assistant.calculate("2 + 2");

        // Verify spans
        List<SpanData> spans = spanExporter.getFinishedSpanItems();

        // Should have: 1 AiService span, 1 LLM span, 1 tool span
        assertThat(spans).hasSizeGreaterThanOrEqualTo(3);

        // Find root AiService span
        SpanData rootSpan = spans.stream()
            .filter(s -> s.getName().startsWith("AiService."))
            .findFirst()
            .orElseThrow();

        assertThat(rootSpan.getAttributes().asMap())
            .containsKey(AttributeKey.stringKey("ai_service.interface"))
            .containsKey(AttributeKey.stringKey("ai_service.method"));

        // Find LLM span
        SpanData llmSpan = spans.stream()
            .filter(s -> s.getKind() == SpanKind.CLIENT)
            .findFirst()
            .orElseThrow();

        assertThat(llmSpan.getAttributes().asMap())
            .containsKey(AttributeKey.stringKey("gen_ai.system"))
            .containsKey(AttributeKey.stringKey("gen_ai.request.model"));

        // Find tool span
        SpanData toolSpan = spans.stream()
            .filter(s -> s.getName().startsWith("tool."))
            .findFirst()
